<script setup lang="ts">
useSeoMeta({ title: 'Produtos | Tecla Nativa', description: 'Explore periféricos, áudio e vídeo, conectividade, casa inteligente e acessórios para sua rotina.' });
const catalog=useStorefrontCatalog();const products=catalog.products;const route=useRoute();const search=ref(String(route.query.busca||''));const category=ref(String(route.query.categoria||''));const sort=ref('destaques');const cats=computed(()=>catalog.categories.value.map(c=>[c.slug,c.name] as const));
const filtered=computed(()=>{let list=products.value.filter(p=>(!category.value||p.category===category.value)&&(!search.value||(p.name+' '+p.summary+' '+p.categoryLabel+' '+p.sku).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(search.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()))); if(sort.value==='menor-preco')list.sort((a,b)=>a.price-b.price);if(sort.value==='maior-preco')list.sort((a,b)=>b.price-a.price);if(sort.value==='nome')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));return list});
function clear(){search.value='';category.value='';sort.value='destaques'}
onMounted(()=>void catalog.refresh());
</script>
<template><div class="page-wrap wrap"><div class="breadcrumb"><NuxtLink to="/">Início</NuxtLink><span>/</span><span>Produtos</span></div><div class="catalog-header"><span class="eyebrow">TECNOLOGIA ESCOLHIDA COM CRITÉRIO</span><h1>O que combina<br/>com a sua <em>rotina.</em></h1><p>Explore a curadoria, compare opções e confira os detalhes de cada produto.</p></div><div class="catalog-toolbar"><div class="catalog-count"><b>{{filtered.length}}</b> produtos <span v-if="category||search">encontrados</span></div><div class="catalog-controls"><label class="sr-only" for="catalog-search">Buscar no catálogo</label><input id="catalog-search" v-model="search" type="search" placeholder="Buscar produto ou categoria"/><label class="sr-only" for="category-select">Filtrar por categoria</label><select id="category-select" v-model="category"><option value="">Todas as categorias</option><option v-for="c in cats" :key="c[0]" :value="c[0]">{{c[1]}}</option></select><label class="sr-only" for="sort-select">Ordenar produtos</label><select id="sort-select" v-model="sort"><option value="destaques">Destaques</option><option value="menor-preco">Menor preço</option><option value="maior-preco">Maior preço</option><option value="nome">Nome A–Z</option></select></div></div><div v-if="filtered.length" class="product-grid catalog-grid"><ProductCard v-for="p in filtered" :key="p.id" :product="p"/></div><div v-else class="empty-state"><span>⌕</span><h2>Não encontramos esse resultado.</h2><p>Tente outro termo ou remova os filtros para ver a curadoria completa.</p><button class="button button-dark" @click="clear">Limpar filtros</button></div><p class="catalog-disclaimer">Valores e disponibilidade são ilustrativos nesta apresentação. Confirme informações antes de uma compra real.</p></div></template>
